program.source:
Algorithm TresEnRaya
  Dimension t[3, 3] As Integer;
  For f <- 0 To 2 Do
    For c <- 0 To 2 Do
      Read t[f, c];
    EndFor
  EndFor
  Define ganador As Integer <- 0;
  For i <- 0 To 2 Do
    If t[i, 0] <> 0 And t[i, 0] = t[i, 1] And t[i, 1] = t[i, 2] Then
      ganador <- t[i, 0];
    EndIf
    If t[0, i] <> 0 And t[0, i] = t[1, i] And t[1, i] = t[2, i] Then
      ganador <- t[0, i];
    EndIf
  EndFor
  If t[1, 1] <> 0 And t[0, 0] = t[1, 1] And t[1, 1] = t[2, 2] Then
    ganador <- t[1, 1];
  EndIf
  Switch ganador Do
    1:
      Write "Gana X";
    2:
      Write "Gana O";
    Otherwise:
      Write "Nadie";
  EndSwitch
EndAlgorithm

